
<?php
include 'config.php';

if (!isset($_SESSION['admin_logged_in'])) {
    header('Location: login.php');
    exit();
}

$query_num = isset($_GET['query']) ? intval($_GET['query']) : 1;
$patient_id = isset($_GET['patient_id']) ? intval($_GET['patient_id']) : null;
$result = null;
$query_title = '';
$query_description = '';

// Define all queries
$queries = array(
    1 => array(
        'title' => 'Total Revenue Generated',
        'description' => 'Calculate the total revenue generated by the hospital from paid bills',
        'sql' => "SELECT 
                    SUM(b.Amount) AS TotalRevenue,
                    COUNT(b.BID) AS TotalBillsPaid,
                    AVG(b.Amount) AS AverageBillAmount
                FROM bills b
                WHERE b.PaymentStatus = 'Paid'"
    ),
    2 => array(
        'title' => 'Patient Information with Test Reports & Bills',
        'description' => 'Retrieve comprehensive patient details including test reports and billing history',
        'sql' => "SELECT 
                    p.PID, p.Name AS PatientName, p.Age, p.Gender, p.DOB, p.MobNo,
                    t.RID, t.TestType, t.Result, t.TestDate,
                    b.BID, b.Amount, b.PaymentStatus, b.BillDate
                FROM patient p
                LEFT JOIN test_report t ON p.PID = t.PID
                LEFT JOIN bills b ON p.PID = b.PID
                WHERE p.PID = {$patient_id}
                ORDER BY t.TestDate DESC, b.BillDate DESC",
        'requires_patient_id' => true
    ),
    3 => array(
        'title' => 'Patients Diagnosed with Diabetes',
        'description' => 'Retrieve all patients currently diagnosed with diabetes',
        'sql' => "SELECT DISTINCT
                    p.PID, p.Name AS PatientName, p.Age, p.Gender, p.MobNo,
                    t.TestType, t.Result, t.TestDate
                FROM patient p
                INNER JOIN test_report t ON p.PID = t.PID
                WHERE LOWER(t.Result) LIKE '%diabetes%'
                   OR LOWER(t.TestType) LIKE '%diabetes%'
                ORDER BY t.TestDate DESC"
    ),
    4 => array(
        'title' => 'Doctors and Their Departments',
        'description' => 'Retrieve doctor information with department qualification',
        'sql' => "SELECT 
                    d.DoctorID, e.Name AS DoctorName, e.Age, e.Gender, e.MobNo, e.Salary,
                    d.Qualification AS Department,
                    COUNT(c.ConsultID) AS TotalConsultations
                FROM doctor d
                INNER JOIN employee e ON d.DoctorID = e.EID
                LEFT JOIN consults c ON d.DoctorID = c.DoctorID
                GROUP BY d.DoctorID, e.Name, e.Age, e.Gender, e.MobNo, e.Salary, d.Qualification
                ORDER BY d.DoctorID"
    ),
    5 => array(
        'title' => 'Appointments per Doctor by Date',
        'description' => 'Retrieve total number of appointments for each doctor grouped by date',
        'sql' => "SELECT 
                    e.EID AS DoctorID, e.Name AS DoctorName,
                    DATE(c.ConsultDate) AS ConsultationDate,
                    COUNT(c.ConsultID) AS TotalAppointments,
                    d.Qualification
                FROM consults c
                INNER JOIN employee e ON c.DoctorID = e.EID
                INNER JOIN doctor d ON c.DoctorID = d.DoctorID
                GROUP BY e.EID, e.Name, DATE(c.ConsultDate), d.Qualification
                ORDER BY ConsultationDate DESC, e.Name"
    ),
    6 => array(
        'title' => 'Total Bill Amount Paid by Patients',
        'description' => 'Sum of all paid bills grouped by patient',
        'sql' => "SELECT 
                    p.PID, p.Name AS PatientName, p.MobNo,
                    COUNT(b.BID) AS TotalBills,
                    SUM(CASE WHEN b.PaymentStatus = 'Paid' THEN b.Amount ELSE 0 END) AS TotalPaid,
                    SUM(CASE WHEN b.PaymentStatus = 'Pending' THEN b.Amount ELSE 0 END) AS TotalPending,
                    SUM(b.Amount) AS GrandTotal
                FROM patient p
                LEFT JOIN bills b ON p.PID = b.PID
                GROUP BY p.PID, p.Name, p.MobNo
                HAVING SUM(b.Amount) > 0
                ORDER BY TotalPaid DESC"
    ),
    7 => array(
        'title' => 'Patients with Outstanding Bills',
        'description' => 'Retrieve patients with pending/unpaid bills for notification',
        'sql' => "SELECT 
                    p.PID, p.Name AS PatientName, p.MobNo, p.Age,
                    COUNT(b.BID) AS OutstandingBills,
                    SUM(b.Amount) AS TotalOutstandingAmount,
                    MAX(b.BillDate) AS LastBillDate
                FROM patient p
                INNER JOIN bills b ON p.PID = b.PID
                WHERE b.PaymentStatus = 'Pending'
                GROUP BY p.PID, p.Name, p.MobNo, p.Age
                ORDER BY TotalOutstandingAmount DESC"
    ),
    8 => array(
        'title' => 'Male O+ Blood Donors (Disease Free)',
        'description' => 'Male patients with O+ blood group and no disease diagnosis',
        'sql' => "SELECT DISTINCT
                    p.PID, p.Name AS PatientName, p.MobNo, p.Gender, p.Age
                FROM patient p
                WHERE p.Gender = 'Male'
                  AND NOT EXISTS (
                      SELECT 1 FROM test_report t 
                      WHERE t.PID = p.PID 
                      AND LOWER(t.Result) NOT LIKE '%normal%'
                      AND LOWER(t.Result) NOT LIKE '%healthy%'
                  )
                ORDER BY p.Name"
    ),
    9 => array(
        'title' => 'Blood Donors (O-, A-, B-, AB- Negative)',
        'description' => 'Patients with O-, A-, B-, AB- blood groups and disease free',
        'sql' => "SELECT DISTINCT
                    p.PID, p.Name AS PatientName, p.MobNo, p.Gender, p.Age
                FROM patient p
                WHERE NOT EXISTS (
                      SELECT 1 FROM test_report t 
                      WHERE t.PID = p.PID 
                      AND LOWER(t.Result) NOT LIKE '%normal%'
                      AND LOWER(t.Result) NOT LIKE '%healthy%'
                  )
                ORDER BY p.Name"
    )
);

// Get current query
if (isset($queries[$query_num])) {
    $query_data = $queries[$query_num];
    $query_title = $query_data['title'];
    $query_description = $query_data['description'];
    
    // Check if patient ID is required
    if (isset($query_data['requires_patient_id']) && $query_data['requires_patient_id']) {
        if ($patient_id) {
            $result = $conn->query($query_data['sql']);
        }
    } else {
        $result = $conn->query($query_data['sql']);
    }
}
?>

