        <?php if ($query_num > 0 && isset($queries[$query_num])): ?>
            <div class="query-info">
                <h2><?php echo $query_title; ?></h2>
                <p><?php echo $query_description; ?></p>
            </div>
            
            <?php if (isset($queries[$query_num]['requires_patient_id']) && $queries[$query_num]['requires_patient_id']): ?>
                <div class="query-selector" style="background: #e3f2fd;">
                    <form method="GET" action="">
                        <div class="form-group">
                            <label>Enter Patient ID:</label>
                            <input type="number" name="patient_id" value="<?php echo $patient_id ?? ''; ?>" required>
                        </div>
                        <input type="hidden" name="query" value="<?php echo $query_num; ?>">
                        <button type="submit" class="btn-search">Search</button>
                    </form>
                </div>
            <?php endif; ?>
            
            <?php if ($result): ?>
                <?php if ($result->num_rows > 0): ?>
                    <table>
                        <thead>
                            <tr>
                                <?php
                                $field_info = $result->fetch_fields();
                                foreach ($field_info as $field) {
                                    echo "<th>" . htmlspecialchars($field->name) . "</th>";
                                }
                                ?>
                            </tr>
                        </thead>
                        <tbody>
                            <?php while ($row = $result->fetch_assoc()): ?>
                                <tr>
                                    <?php foreach ($row as $value): ?>
                                        <td><?php echo htmlspecialchars($value ?? 'N/A'); ?></td>
                                    <?php endforeach; ?>
                                </tr>
                            <?php endwhile; ?>
                        </tbody>
                    </table>
                <?php else: ?>
                    <div class="no-data">
